  "Archived": "В архіві",
  "Archived (N) opens a panel to find archived cards, restore them to any lane, restore all or delete for good. It shows where each card came from.": "«В архіві (N)» відкриває панель, де можна знайти архівовані картки, відновити їх у будь-яку колонку, відновити всі або видалити назавжди. Видно, звідки прийшла кожна картка.",
