  "Ask Mnemo here; it answers under the line": "Запитай Mnemo тут; відповідь з’явиться під рядком",
  "Ask Mnemo what is overdue across your boards; it can tick cards off or move them for you, and agents get the same over MCP.": "Запитайте Mnemo, що прострочено на всіх ваших дошках; він може позначити картки або перемістити їх за вас, а агенти отримують те саме через MCP.",
  "Ask about the folder {name}, or anything in your vault.": "Питай про папку {name} або про будь-що у сховищі.",
  "Ask about {name}, or anything in your vault.": "Питай про {name} або про будь-що у сховищі.",
  "Ask before sub-agents run": "Питати перед запуском субагентів",
  "Ask first": "Спершу питати",
  "Ask first: {mnemo} asks before changes": "Спершу питати: {mnemo} питає перед змінами",
