  "Ask first: {mnemo} reads freely but asks before it changes notes or runs sub-agents. Auto: changes and sub-agents go ahead without asking. Read only: it reads and answers, and never changes notes. Saved at once.": "Спершу питати: {mnemo} вільно читає, але питає, перш ніж змінювати нотатки чи запускати субагентів. Авто: зміни та субагенти виконуються без питань. Лише читання: він читає й відповідає, але ніколи не змінює нотатки. Зберігається одразу.",
  "Ask privately… nothing here is kept": "Питай приватно… тут нічого не зберігається",
  "Ask {mnemo}": "Запитати {mnemo}",
