  "Board and note menus offer only what belongs there, the lane menu is grouped with a colour row, and Embed in a note searches as you type.": "У меню дошок і нотаток лише потрібне, меню колонки згруповане з рядком кольорів, а «Вбудувати в нотатку» шукає під час введення.",
