  "Browsers signed in to your account. Tap ⋯ to name a device, see its sign-ins or sign it out. Connected agents are not listed here and keep working.": "Браузери, у яких виконано вхід у твій обліковий запис. Натисни ⋯, щоб назвати пристрій, побачити його входи або вийти з нього. Підключені агенти тут не показані й продовжують працювати.",
