  "Bulleted list": "Маркований список",
  "Button does nothing? Choose <b>Copy setup instead</b> and paste it into <code>~/.cursor/mcp.json</code> (create the file when missing).": "Кнопка не діє? Вибери <b>Скопіювати налаштування</b> і встав у <code>~/.cursor/mcp.json</code> (створи файл, якщо його немає).",
  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "Кнопка не діє? Вибери <b>Скопіювати налаштування</b>, запусти <b>MCP: Open User Configuration</b> з палітри команд і встав туди. VS Code використовує <code>servers</code>, а не <code>mcpServers</code>.",
  "By": "Автор",
  "Call the Memora healthcheck tool, then search my memory for \"project\".": "Виклич інструмент перевірки стану Memora, потім знайди в моїй пам’яті «project».",
