  "Cards moved here are marked done": "Картки, перенесені сюди, позначаються як виконані",
  "Cards that are overdue, due today or due this week, from every board, each with its board and lane. Open a card on its board or tick it off right there.": "Прострочені картки та картки зі строком сьогодні чи цього тижня з усіх дошок, у кожної вказано дошку й колонку. Відкрийте картку на її дошці або одразу позначте її.",
