  "Chat width": "Ширина чату",
  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Спілкуйся з обраною моделлю; {mnemo} читає, пише, тегує, зв’язує, переміщує й упорядковує нотатки власними інструментами Memora. Він не може переглядати веб, запускати команди, видаляти назавжди чи змінювати сервер. Ключі запечатані на цьому сервері й ніколи не надсилаються в браузер.",
  "Chat with your notes agent": "Чат із твоїм агентом для нотаток",
  "ChatGPT only signs in over OAuth; it cannot send a key header.": "ChatGPT входить лише через OAuth; він не може надсилати заголовок із ключем.",
  "Chats": "Чати",
  "Check and fix on the server": "Перевірити й виправити на сервері",
