  "Choose between 0.1 and 50 MB": "Вибери від 0,1 до 50 МБ",
  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "Обирай із багатьох мов у Налаштуваннях, Вигляд, для кожного пристрою. Авто слідує за твоїм браузером.",
  "Choose your vault folder": "Вибери папку свого сховища",
  "Chosen colour": "Обраний колір",
  "Chosen when it signs in": "Обирається під час входу",
  "Claude Desktop (older)": "Claude Desktop (старіший)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude і ChatGPT входять через твій обліковий запис Memora. Копіювати нічого не треба.",
  "Claude models": "Моделі Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude входить через OAuth, тож ключ вставляти не треба: він отримує власний ключ, коли ти натискаєш «Дозволити». Без входу підключи його як <b>Інший застосунок</b> і надсилай заголовок <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor та інші",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor та інші, кожен зі своїм ключем",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex та інші отримують власний доступ, тож ти бачиш, що робить кожен.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT і твій власний агент ділять одну Memora, доступну з цього комп’ютера, локальної мережі чи інтернету",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Claude, Cursor, ChatGPT і твої власні скрипти читають твої нотатки та доповнюють їх.",
