  "Click <b>Add</b>, then <b>Connect</b>. A Memora page opens: sign in if asked and press <b>Allow</b>.": "Натисни <b>Додати</b>, потім <b>Підключити</b>. Відкриється сторінка Memora: увійди, якщо попросить, і натисни <b>Дозволити</b>.",
