  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Перетягни картку в рамку іншої папки, щоб перемістити нотатку на диску. Перетягни рамку за назву, щоб змінити розташування на дошці; кинь її на іншу рамку, щоб перемістити туди всю папку. Двічі клацни заголовок, щоб перейменувати. На сенсорному екрані: перетягуй для панорами, щипком масштабуй, довго тримай картку, щоб її перемістити, торкнись для перегляду.",
  "Drag a note here to pin it": "Перетягни сюди нотатку, щоб закріпити",
  "Drag notes or folders here to pin them": "Перетягни сюди нотатки чи папки, щоб закріпити",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Перетягни нотатки чи папки на папку, щоб перемістити, або на «Закріплені», щоб закріпити.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Перетягуй нотатки · двічі клацни, щоб закріпити · / пошук · #тег шукає теги · F вмістити · 1 2 3 розкладки",
  "Drag to move the folder frame; double-click to rename": "Перетягни, щоб перемістити рамку папки; двічі клацни, щоб перейменувати",
  "Drag to move the lane. Double click the name to rename it.": "Перетягни, щоб перемістити колонку. Двічі клацни по назві, щоб перейменувати.",
  "Drag to resize · double-click to reset": "Перетягни, щоб змінити розмір · двічі клацни, щоб скинути",
  "Drag to turn · scroll to zoom · click a point to open its note": "Перетягни, щоб повернути · прокрути для масштабу · клацни точку, щоб відкрити нотатку",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Перетягни, щоб повернути · прокрути для масштабу · клацни точку, щоб відкрити нотатку · / пошук · #тег шукає теги",
  "Draw a chart of how many notes I write each week": "Намалюй діаграму, скільки нотаток я пишу щотижня",
