  "Each AI app connects over MCP with its own key and permissions.": "Кожен ШІ-застосунок підключається через MCP зі своїм ключем і дозволами.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Кожен підключений ШІ-застосунок — це агент зі своїм ключем, тож ти бачиш, що робить кожен, і можеш вимкнути будь-якого окремо.",
  "Each agent": "Кожен агент",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Кожен агент належить одному застосунку. Для іншого застосунку чи пристрою створи нового агента.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Кожен агент належить одному застосунку. Щоб використовувати Memora в іншому застосунку, створи для нього окремого агента.",
  "Each app gets its own key": "Кожен застосунок отримує власний ключ",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Кожен має короткий ID, що ніколи не змінюється, тож імена можна міняти вільно. Mnemo створює їх, змінює вказівки чи модель, пише їм, чекає, зупиняє, завершує й видаляє — по одному або всіх разом — і може залишити їх працювати у фоні. На кожній картці видно Завдання, Активність і Відповідь.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Кожен вид міряється власним запасом: його лімітом, якщо задано, інакше тим, що він займає, плюс вільне місце на диску{disk}. Порожній ліміт: без обмеження.",
  "Each one gets its own key from Memora.": "Кожен отримує від Memora власний ключ.",
