  "Every action, newest first, with search and filters.": "Кожна дія, найновіші першими, з пошуком і фільтрами.",
  "Every address from one to another.": "Усі адреси від однієї до іншої.",
  "Every address from the first to the last, joined by a dash.": "Усі адреси від першої до останньої, з’єднані тире.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Кожен агент зазвичай починає з нуля. {bold} підключи кожного агента один раз, і всі читатимуть те саме сховище й писатимуть у нього, тож що вивчив один, можуть використати інші.",
  "Every archived card is back on the board": "Усі архівовані картки знову на дошці",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Кожна дошка зі своїми колонками та прогресом. «Нова дошка» є всюди, де є «Нова нотатка»: на бічній панелі, в Огляді, папках, меню, пошуку та на клавіші B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Усі браузери й агенти відключені, доки хтось знову не запустить Memora на цій машині. Ця сторінка не може запустити її знову.",
  "Every call shows up live in the brain and Activity": "Кожен виклик одразу видно в мозку й Активності",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Кожна зміна Mnemo видна в Активності й може бути скасована з Історії.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Кожна зміна, твоя чи застосунку, видна в Активності й може бути скасована з Історії.",
  "Every chat is archived.": "Усі чати заархівовано.",
  "Every chat with your notes agent": "Усі чати з твоїм агентом для нотаток",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Кожен підключений ШІ одразу втрачає всі інструменти ({n}) і більше не може читати чи змінювати твої нотатки, доки ти не ввімкнеш інструменти тут знову.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Кожен підключений ШІ одразу втрачає його. Можна знову ввімкнути будь-коли.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Кожен підключений ШІ одразу втрачає їх. Можна знову ввімкнути будь-коли.",
  "Every connected agent loses its memory until Memora runs again.": "Кожен підключений агент втрачає пам’ять, доки Memora не запрацює знову.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Усі пристрої в домашній чи офісній мережі, записані як адреса/розмір: 192.168.1.0/24 охоплює від 192.168.1.0 до 192.168.1.255.",
  "Every device on a home or office network.": "Усі пристрої в домашній чи офісній мережі.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Кожне зображення в папці нотаток і де воно показане, а також зображення, що зберігаються для чатів Mnemo.",
  "Every image is used in a note.": "Кожне зображення використано в нотатці.",
  "Every note": "Кожна нотатка",
  "Every note and link, in 3D, as a graph or on a board.": "Кожна нотатка й посилання: у 3D, як граф або на дошці.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Усі нотатки й підпапки в «{path}» переміщуються в {folder}; потім «{name}» видаляється. Якщо ім’я там уже зайняте, додається число.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Кожна нотатка стає тут карткою в рамці своєї папки. Посібник покаже, як змусити ШІ зберегти знання тут або написати нотатку самому.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Кожна нотатка стає тут точкою світла, згрупованою за папками. Посібник покаже, як змусити ШІ зберегти знання тут або написати нотатку самому.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Кожна нотатка з тегом #{tag} ({notes}) отримає нову назву, вбудовані #теги в тексті теж.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Кожна нотатка з тегами {tags} отримає один тег замість них ({notes}). Вбудовані #теги в тексті теж змінюються. Скасувати одним кроком не можна; кожна нотатка зберігає свою історію.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Кожне читання й запис агента видно наживо, тож ти завжди знаєш, хто що робив.",
  "Every request that reaches this rule is {verb}.": "Кожен запит, що доходить до цього правила, {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Кожен запит. Став його останнім, щоб зловити все, що не спіймали правила вище.",
  "Every setting and where it lives.": "Кожне налаштування й де воно розташоване.",
  "Every shortcut in the web UI.": "Усі скорочення у вебінтерфейсі.",
  "Every tag and its notes": "Кожен тег і його нотатки",
