  "For": "Для",
  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "Для автентифікації вибери <b>OAuth</b>, залиш ID клієнта й секрет порожніми та натисни <b>Create</b>. Відкриється сторінка Memora: натисни <b>Allow</b>.",
  "For example: Product launch": "Наприклад: Запуск продукту",
