  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "Відтепер, коли я кажу тобі щось важливе, зберігай це в Memora. Спробуй зараз: збережи нотатку про те, що я сьогодні почав користуватися Memora.",
