  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Збираю справжню активність за {range}. У великому журналі це може тривати, зачекай.",
  "General": "Загальне",
  "Get a one-time code on the server": "Отримати одноразовий код на сервері",
  "Get started": "Почати",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Пізнай мене за моїми нотатками. Перегляни моє сховище (нещодавні нотатки, щоденники, проєкти, усе про мене) і збережи те, що дізнаєшся, через remember_owner: хто я, над чим працюю, які відповіді люблю, що мені подобається. Лише короткі й тривалі речі, жодних секретів. Потім кількома рядками розкажи, що ти зберіг.",
  "Gets its own agent key: read and write nodes over MCP": "Отримує власний ключ агента: читання й запис вузлів через MCP",
  "Getting started": "Початок роботи",
  "GitHub answered HTTP {code}": "GitHub відповів HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Дай Claude, Cursor чи будь-якому застосунку MCP власний ключ, а потім нехай збереже те, що вже знає про тебе.",
  "Give a key read-only access, or let it write too.": "Дай ключу доступ лише для читання або дозволь і писати.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Дай кожному застосунку чи пристрою власного агента. Тоді Активність покаже, хто що зробив, і ти зможеш вимкнути одного, не чіпаючи інших.",
