  "How Memora looks for you. Saved in this browser only.": "Як Memora виглядає для тебе. Зберігається лише в цьому браузері.",
  "How far apart the folder islands of the Clusters layout are.": "Наскільки далеко один від одного острови папок у розкладці «Кластери».",
  "How far apart the rings of the Radial layout are.": "Наскільки далеко одне від одного кільця в радіальній розкладці.",
  "How full notes, images and chats are, and their limits": "Наскільки заповнені нотатки, зображення й чати та їхні ліміти",
  "How hard notes push each other apart in the Force layout.": "Наскільки сильно нотатки відштовхуються в розкладці «Сила».",
  "How it works": "Як це працює",
  "How large an image may be, and what images take": "Який розмір може мати зображення й що займають зображення",
  "How many notes": "Скільки нотаток",
  "How much history the server keeps": "Скільки історії зберігає сервер",
  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Скільки місця займають нотатки, зображення й чати Mnemo, кожне щодо власного запасу. Банер попереджає, коли щось майже заповнене.",
  "How the agent itself shows up: its display name and colour.": "Як сам агент виглядає: його відображуване ім’я та колір.",
  "How to update": "Як оновити",
  "How {mnemo} works": "Як працює {mnemo}",
  "Humanist": "Гуманістичний",
  "Hyphenate long words": "Переносити довгі слова",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Я знаходжу, читаю, пишу, тегую, зв’язую й упорядковую твої нотатки. Без вебу й оболонки: лише твоє сховище.",
  "Icon": "Значок",
  "Icon {name}": "Значок {name}",
  "Ideas grow when they connect. Link this note to {a} or read {b}.": "Ідеї ростуть, коли поєднуються. Пов’яжіть цю нотатку з {a} або прочитайте {b}.",
  "Identity": "Ідентичність",
  "Idle": "Вільний",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Якщо тобі це стало в пригоді, зірка на GitHub або порада другові допоможе іншим знайти проєкт. Якщо ні — нічого страшного.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Якщо вийдеш, вони збережуться на цьому пристрої й будуть запропоновані знову, коли відкриєш нотатку.",
  "Image": "Зображення",
  "Image (or paste or drop one)": "Зображення (або встав чи перетягни)",
  "Image deleted": "Зображення видалено",
  "Image line copied": "Рядок зображення скопійовано",
  "Image you attached": "Зображення, яке ти прикріпив",
  "Image {name}": "Зображення {name}",
  "Images": "Зображення",
  "Images can now be up to {n} MB": "Зображення тепер можуть бути до {n} МБ",
  "Images in this folder": "Зображення в цій папці",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Зображення лежать поруч із нотатками, що їх показують. Вибери, якого розміру вони можуть бути, і дивись, що займають нотатки й зображення.",
  "Import and export": "Імпорт і експорт",
  "Imported": "Імпортовано",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "У ChatGPT відкрий <b>Settings → Apps &amp; Connectors → Advanced settings</b> і ввімкни <b>Developer mode</b>. Потім вибери <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "У Claude (веб чи десктоп) відкрий <b>Settings → Connectors</b> і вибери <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "У Claude Desktop відкрий <b>Settings → Developer → Edit Config</b>. У новіших версіях вибери <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "У Windsurf відкрий <b>Settings → Cascade → MCP servers</b> і вибери <b>View raw config</b>.",
  "In colour": "Кольорові",
  "In note text": "У тексті нотатки",
  "In notes": "У нотатках",
  "In search: actions only (new note, theme ...)": "У пошуку: лише дії (нова нотатка, тема ...)",
