  "Lane actions": "Дії з колонкою",
  "Lane color": "Колір колонки",
  "Lane deleted": "Колонку видалено",
  "Lane dots stay at the bottom of the board, and long lane titles end in … with the full title on a tap.": "Крапки колонок лишаються внизу дошки, а довгі назви колонок закінчуються на …, повна назва видна за дотиком.",
  "Lane name": "Назва колонки",
  "Lane width": "Ширина колонок",
  "Lanes": "Колонки",
  "Lanes are the columns of the board, such as To do, Doing and Done.": "Колонки — це стовпці дошки, наприклад «Зробити», «В роботі» та «Готово».",
  "Lanes fade at the edge while there is more to see, snap one at a time on phones with dots to jump between them, and links, tags and mentions on cards show as chips.": "Колонки згасають біля краю, поки є що подивитися, на телефонах гортаються по одній, а крапки допомагають переходити між ними; посилання, теги та згадки на картках показуються як чипи.",
  "Lanes of cards to drag, tick off and share with agents": "Колонки карток, щоб перетягувати, позначати й ділитися з агентами",
