  "Less for one AI.": "Менше для одного ШІ.",
  "Let in or keep out addresses and networks before anyone sees the sign-in page.": "Впускай або не пускай адреси й мережі до того, як хтось побачить сторінку входу.",
  "Let it connect again with the same key.": "Дозволити йому знову підключатися з тим самим ключем.",
  "Let it in. People still sign in and AIs still need their key.": "Впустити. Люди все одно входять, а ШІ все одно потрібен ключ.",
  "Let {mnemo} learn about me": "Нехай {mnemo} дізнається про мене",
  "Let's fill your memory": "Наповнімо твою пам’ять",
  "Lets the app use Memora's tools (MCP), limited by the tool list below. Every AI app needs this.": "Дозволяє застосунку користуватися інструментами Memora (MCP) в межах списку нижче. Потрібно кожному ШІ-застосунку.",
  "Letters, digits and dashes. Made from the name; edit it if you like.": "Літери, цифри й дефіси. Створюється з назви; відредагуй, якщо хочеш.",
