  "Long chats, light": "Довгі чати — легко",
  "Long enough. A few more characters make it stronger.": "Достатньо довгий. Ще кілька символів зроблять його надійнішим.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Довші завдання показуються як чекліст над полем повідомлення: не розпочато, у процесі, готово.",
  "Longest sign-in": "Найдовший вхід",
  "Longest sign-in must be at least the inactivity time": "Найдовший вхід має бути не коротшим за час бездіяльності",
  "Look for tags that mean the same thing": "Шукати теги з однаковим змістом",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Перегляньте проєкт у цій папці й збережи його в Memora: для чого він, як побудований, як запускається, технічні рішення й усе, що варто пам’ятати. Зроби одну нотатку на тему, у папці з назвою проєкту всередині Projects.",
