  "Main navigation": "Головна навігація",
  "Make a new key": "Створити новий ключ",
  "Make a new key first": "Спершу створи новий ключ",
  "Make a new key for {name} first": "Спершу створи новий ключ для {name}",
  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "Створи агента для кожного застосунку чи пристрою, яким користуєшся. Кожен отримує власний ключ, тож ти бачиш, що він робить, і можеш вимкнути його окремо.",
