  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Не виконано: Mnemo у режимі «Спершу питати», тож зміни чекають на згоду власника. Запитай через ask_owner (скажи, що змінюватимеш; дай варіант із approve: true, наприклад «Так, давай»), потім зміни після схвалення.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Не виконано: Mnemo у режимі «Лише читання», тож нотатки не змінюються. Скажи, що змінив би; власник може перемкнути на «Спершу питати» чи «Авто» в чаті.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Не виконано: чат у режимі «Спершу питати», тож субагент не може змінювати нотатки. Напиши у відповіді, що змінити; Mnemo запитає власника.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Не виконано: власник вимкнув {tool} для Mnemo (Налаштування, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Не виконано: власник вимкнув {tool} для субагентів (Налаштування, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Не завершено: власник обірвав цю відповідь до того, як інструмент повернувся.",
  "Not found": "Не знайдено",
  "Not from AI apps": "Не від ШІ-застосунків",
  "Not in your models": "Немає серед твоїх моделей",
  "Not kept · gone when you leave it": "Не зберігається · зникає, коли залишиш",
  "Not kept: nothing is learned about the owner here.": "Не зберігається: тут нічого не дізнаються про власника.",
  "Not known yet": "Ще невідомо",
  "Not loaded": "Не завантажено",
  "Not now": "Не зараз",
  "Not set": "Не задано",
  "Not set up yet": "Ще не налаштовано",
  "Not shown in a note": "Не показано в нотатці",
  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "Не запущено: «{name}» підходить до кількох моделей або жодної точно. Близькі: {list}. Запитай власника, яку, або дай точний ID.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "Не запущено: тут немає моделі «{name}». Скажи власнику або пропусти model, щоб використати його модель за замовчуванням.",
  "Not sure it is on? Ask {app}: “{question}”": "Не певен, що ввімкнено? Запитай {app}: «{question}»",
  "Not used": "Не використовується",
  "Not writable": "Не можна записувати",
  "Note": "Нотатка",
  "Note actions": "Дії з нотаткою",
  "Note change": "Зміна нотатки",
  "Note changes": "Зміни нотаток",
  "Note created": "Нотатку створено",
  "Note deleted": "Нотатку видалено",
  "Note details": "Подробиці нотатки",
  "Note labels": "Підписи нотаток",
  "Note moved or renamed": "Нотатку переміщено або перейменовано",
