  "Open Mnemo chats": "Відкрити чати Mnemo",
  "Open Notes": "Відкрити Нотатки",
  "Open Settings, Notes folder": "Відкрити Налаштування, Папка нотаток",
  "Open Trash": "Відкрити Кошик",
  "Open activity": "Відкрити активність",
  "Open agent activity": "Відкрити активність агента",
  "Open boards": "Відкрити дошки",
