  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "Минулі терміни виділяються кольором попередження, сьогоднішні — м’якшим, а сторінка «Дошки» рахує прострочене. Власні кольори дат дошки мають пріоритет.",
