  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Встав це в термінал і натисни <kbd>Enter</kbd>, потім запусти Codex у тому самому терміналі.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Встав це в термінал і натисни <kbd>Enter</kbd>. Потім запусти Claude Code або перезапусти його: Memora завантажиться сама.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Встав це в термінал і натисни <kbd>Enter</kbd>. Потім запусти Gemini CLI або перезапусти його і введи <code>/mcp</code>, щоб побачити Memora.",
  "Paste it into the app where it asks for a key.": "Встав це в застосунок там, де він просить ключ.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Встав це у файл і збережи, потім натисни <b>Refresh</b>. Memora з’явиться в списку.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Встав це у файл, збережи й перезапусти Claude Desktop. Потрібен Node.js на цьому комп’ютері.",
