  "{mnemo} asks this model when you want a picture made.": "{mnemo} звертається до цієї моделі, коли ти хочеш створити картинку.",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "Кнопку {mnemo} сховано. Поверни її через «Ще», «Показати кнопку {mnemo}».",
  "{mnemo} button hidden. Show it again here or from More.": "Кнопку {mnemo} сховано. Покажи її знову тут або через «Ще».",
