  "{mnemo} looks after your notes": "{mnemo} дбає про твої нотатки",
  "{mnemo} may learn about you": "{mnemo} може дізнаватися про тебе",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} працює лише у твоїх нотатках. Кожна зміна видна в Активності й може бути скасована з Історії.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} читає твоє сховище в новому чаті й зберігає тут те, що дізнається.",
  "{mnemo} settings saved": "Налаштування {mnemo} збережено",
  "{mnemo} settings: models and keys": "Налаштування {mnemo}: моделі й ключі",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} сам запускає субагентів, коли завдання добре ділиться; налаштовувати нічого не треба. Вони працюють на твоїй моделі за замовчуванням, потім на резервних, якщо ти не вкажеш модель у чаті. Стеж за ними й перемикай їхню модель у «Агентах» угорі праворуч у чаті. Вони витрачають власні токени, тож у режимі «Спершу питати» {mnemo} питає й називає приблизну кількість; в «Авто» просто запускає. Зберігається одразу.",
  "{mnemo} stopped it": "{mnemo} зупинив його",
  "{mnemo} will keep that in mind": "{mnemo} це врахує",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} пише нові підказки за твоїми нещодавніми нотатками (твої лишаються)",
  "{mnemo}'s own ({n})": "Власні ({n}) {mnemo}",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "Власні нотатки {mnemo} про те, як з тобою говорити, читаються в кожному чаті. Натисни, щоб змінити.",
  "{mnemo}, your notes agent": "{mnemo}, твій агент для нотаток",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} не бачить зображень; отримала лише їхні назви. Задай у Налаштуваннях модель, що читає зображення, щоб їх бачили.",
  "{model} cannot look at images; the image model described them for it.": "{model} не бачить зображень; модель зображень описала їх для неї.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} не читає картинки, тож отримує лише їхні назви. Задай модель, що читає зображення, або змін модель цього чату.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} не читає картинки, тож отримала лише їхні назви. Задай модель, що читає зображення, або змін модель цього чату.",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} не читає картинки, тож модель зображень подивилася їх за неї.",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} не читає картинки, тож модель зображень дивиться їх за неї.",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} не відповіла ({why}); пробую знову через {wait} с ({n}/{total})…",
  "{model} is answering": "{model} відповідає",
  "{model} is the default for new chats": "{model} тепер за замовчуванням для нових чатів",
  "{model} takes over from {agent}'s next step (it is working now), and answers its follow-ups in this chat. It may work a little differently from {prev}.": "{model} перебирає від наступного кроку {agent} (він працює зараз) і відповідає на його уточнення в цьому чаті. Вона може працювати трохи інакше, ніж {prev}.",
  "{model} takes over from {agent}'s next step, and answers its follow-ups in this chat. It may work a little differently from {prev}.": "{model} перебирає від наступного кроку {agent} і відповідає на його уточнення в цьому чаті. Вона може працювати трохи інакше, ніж {prev}.",
